import re

def _norm(recs):
    keys = []
    for r in recs:
        for k in r:
            if k not in keys:
                keys.append(k)
    return [dict((k, r.get(k, '')) for k in keys) for r in recs]

def parse(lines):
    skip = []
    pools = []; pl = []
    members = []; ml = []
    ptraf = []; ptl = []
    mtraf = []; mtl = []
    pool = None; member = None; rec = None
    sec = None; cols = []; tind = -1
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        ind = len(l) - len(l.lstrip())
        if re.match(r'^-{5,}$', s) or re.search(r'\)#\s', l) or re.match(r'^\S+@\S.*#', l):
            skip.append(i)
            continue
        m = re.match(r'^Ltm::Pool Member:\s*(.+?)\s*$', s)
        if m:
            member = m.group(1)
            rec = {'Pool': pool, 'Member': member}
            members.append(rec); ml.append(i)
            sec = None; cols = []
            continue
        m = re.match(r'^Ltm::Pool:\s*(.+?)\s*$', s)
        if m:
            pool = m.group(1); member = None
            rec = {'Pool': pool}
            pools.append(rec); pl.append(i)
            sec = None; cols = []
            continue
        m = re.match(r'^(?P<k>\S.*?)\s+:\s?(?P<v>.*)$', s)
        if m and rec is not None:
            rec[m.group('k')] = m.group('v').strip()
            if member is not None:
                ml.append(i)
            else:
                pl.append(i)
            continue
        if sec is None or ind <= tind:
            parts = re.split(r'\s{2,}', s)
            sec = parts[0]; cols = parts[1:]; tind = ind
            skip.append(i)
            continue
        if cols:
            t = s.split()
            n = len(cols)
            if len(t) > n:
                row = {'Pool': pool}
                if member is not None:
                    row['Member'] = member
                row['Section'] = sec
                row['Statistic'] = ' '.join(t[:-n])
                for c, v in zip(cols, t[-n:]):
                    row[c] = v
                if member is not None:
                    mtraf.append(row); mtl.append(i)
                else:
                    ptraf.append(row); ptl.append(i)
                continue
    blocks = []
    if pools:
        blocks.append({'name': 'pool_status', 'kind': 'kv', 'lines': pl, 'records': pools})
    if ptraf:
        blocks.append({'name': 'pool_traffic', 'kind': 'table', 'lines': ptl, 'records': _norm(ptraf)})
    if members:
        blocks.append({'name': 'members', 'kind': 'table', 'lines': ml, 'records': _norm(members)})
    if mtraf:
        blocks.append({'name': 'member_traffic', 'kind': 'table', 'lines': mtl, 'records': _norm(mtraf)})
    return {'blocks': blocks, 'skip': skip}
